    def add_partnership(
        self,
        *,
        brand: str | None = None,
        attributes: dict[str, Any] | None = None,
        name: str | None = None,
        stage: str | None = None,
        type: str,
        website: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Add a partnership prospect by website.

        Scope: customers.manage. Adds a partner to one of the brand's
        partnership pipelines (a record type a partnerships kit set up, such
        as `link_partnership`, `sponsorship`, `integration_partnership`,
        `affiliate_partnership` or `comparison_listing`) from its website:
        it finds or adds the company record for the site's domain, then adds
        the partnership linked to it (`company`) at `stage`, or the
        pipeline's first stage. `attributes` sets the pipeline's other
        fields, as on `POST .../records`. When the company is already in
        that pipeline, it returns that partnership as it is, with `created`
        false (200). Each value is in the record's history. A pipeline with a
        `domain_rating` field gets the site's rating from the brand's backlinks
        and competitor scans (source `enrichment`) unless `attributes` gives one.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/partnerships
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/partnerships",
            path={"brand": brand},
            body={"attributes": attributes, "name": name, "stage": stage, "type": type, "website": website},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def add_product_name(
        self,
        *,
        brand: str | None = None,
        product_id: str | None = None,
        source: Literal["event", "billing"] | None = None,
        status: Literal["held", "mapped", "ignored"] | None = None,
        value: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Map or ignore a product name before it is seen.

        Scope: customers.manage. status is mapped (the default, with product_id) or ignored.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/product-names
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/product-names",
            path={"brand": brand},
            body={"product_id": product_id, "source": source, "status": status, "value": value},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def add_record_identity(
        self,
        record: str,
        *,
        brand: str | None = None,
        namespace: str,
        properties: dict[str, Any] | None = None,
        replaces: str | None = None,
        source: str | None = None,
        value: str,
        verified: bool | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Add, verify or change an identity.

        Scope: customers.manage. Adds an identity, or updates the record's own copy of it: sending verified: true for
        an email the record holds unverified verifies it (200). When a person changes their email, send the new one
        with replaces set to the old identity's id: the old one is closed as changed and kept in the history. A
        verified value another record of the same brand holds is refused with identity_taken, never moved or merged;
        another brand's person with the same value is someone else and never blocks it.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/records/{record}/identities
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/records/{record}/identities",
            path={"record": record, "brand": brand},
            body={
                "namespace": namespace,
                "properties": properties,
                "replaces": replaces,
                "source": source,
                "value": value,
                "verified": verified,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def add_record_relationship(
        self,
        record: str,
        *,
        brand: str | None = None,
        kind: str,
        properties: dict[str, Any] | None = None,
        to: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Link two records.

        Scope: customers.manage. A typed link from this record, such as partner_of. Record reference fields (companies) are set through attributes instead.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/records/{record}/relationships
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/records/{record}/relationships",
            path={"record": record, "brand": brand},
            body={"kind": kind, "properties": properties, "to": to},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

