    def add_sending_domain_dns(
        self,
        domain: str,
        *,
        ws: str | None = None,
        dkim: list[str] | None = None,
        integration_id: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Add a domain's missing mail records in one click.

        Scope: mailboxes.manage. Adds the records the domain's issues ask for (`issues[].record`: a missing MX, SPF or DMARC record) and, with `dkim`, its DKIM key, through the workspace's own DNS host connection (such as Cloudflare), in the background. It only adds records, never changes or deletes one, so an SPF record missing its mail host's include (`spf_provider`) is left to the approval link or to you. Poll the domain: `dns_install` says how it went, and the domain is checked again once they're in. 400 when nothing is missing or `dkim` isn't a key from the domain's mail host.

        Needs: the mailboxes.manage scope.
        POST /v1/workspaces/{ws}/sending-domains/{domain}/dns
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/sending-domains/{domain}/dns",
            path={"domain": domain, "ws": ws},
            body={"dkim": dkim, "integration_id": integration_id},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def add_seo_competitor(
        self,
        *,
        brand: str | None = None,
        aliases: list[str] | None = None,
        host: str,
        name: str | None = None,
        site_id: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Track a competitor.

        Scope: seo.manage. Tracks a domain as one of a site's competitors
        (a suggestion or dismissed one becomes tracked), with no limit,
        and queues OutflareBot's first light look at it. Its numbers come
        with the connection's next weekly snapshot (or POST .../seo/{id}/sync).
        `host` may be a URL; it is kept as the domain without www.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/seo-competitors
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/seo-competitors",
            path={"brand": brand},
            body={"aliases": aliases, "host": host, "name": name, "site_id": site_id},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def add_seo_site_dns(
        self,
        site: str,
        *,
        brand: str | None = None,
        integration_id: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Add a site's DNS proof in one click.

        Scope: seo.manage. Adds the TXT record in `verification` through the workspace's own DNS host connection (such as Cloudflare), in the background. It only adds records, never changes or deletes one. Poll the site: `dns_install` says how it went, and Outflare looks for the proof every minute until the site is verified.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/seo-sites/{site}/dns
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/seo-sites/{site}/dns",
            path={"site": site, "brand": brand},
            body={"integration_id": integration_id},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

