    def create_action_grant(
        self,
        *,
        ws: str | None = None,
        brand: str | None = None,
        daily_limit: int | None = None,
        daily_spend_cents: int | None = None,
        match: dict[str, Any] | None = None,
        method: Literal["POST", "PUT", "PATCH", "DELETE"] | None = None,
        mode: Literal["run", "hold", "refuse"],
        monthly_spend_cents: int | None = None,
        note: str | None = None,
        path: str,
        token_id: str,
        total_spend_cents: int | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Let an agent token make a kind of change.

        Scope: actions.manage, and a signed-in person only, so no agent can widen its own room. A grant says what happens
        to an agent token's changes that match it: run, hold for a person, or refuse. The most specific matching grant
        decides: one naming the method beats one that doesn't, then the longest path. With no match the change is held.
        Some changes always wait for a person whatever the grants say (mailboxes, sending, sign-ins, tokens, webhooks,
        connections, suppressions, company context, and fixes fix autonomy holds).

        Needs: the actions.manage scope.
        POST /v1/workspaces/{ws}/action-grants
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/action-grants",
            path={"ws": ws},
            body={
                "brand": brand,
                "daily_limit": daily_limit,
                "daily_spend_cents": daily_spend_cents,
                "match": match,
                "method": method,
                "mode": mode,
                "monthly_spend_cents": monthly_spend_cents,
                "note": note,
                "path": path,
                "token_id": token_id,
                "total_spend_cents": total_spend_cents,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_ad_conversion_rule(
        self,
        *,
        ws: str | None = None,
        account_id: str,
        conversion: str | None = None,
        currency: str | None = None,
        enabled: bool | None = None,
        event_name: str | None = None,
        event_type: str | None = None,
        fixed_value_micros: int | None = None,
        target_id: str,
        value_property: str | None = None,
        value_unit: Literal["major", "minor"] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Send a customer event to an ad platform as a conversion.

        Scope: integrations.manage. From now on, each time the event
        happens, the ad platform hears about it server to server within a
        few minutes, with the ad click id from the person's visits and their
        hashed email and phone, so its reporting and bidding learn from real
        outcomes. Events from before the rule are never sent. The event id
        is the one the browser pixel sends, so the platform counts each
        conversion once. Consent follows GET .../ads/settings. The target is
        checked with the platform first. Name a conversion definition (conversion) instead of an event to send only the
        events that meet its conditions, worth what it says unless the rule sets a value, as the event type it names for
        this network when the target offers it.

        Needs: the integrations.manage scope.
        POST /v1/workspaces/{ws}/ads/conversion-rules
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/ads/conversion-rules",
            path={"ws": ws},
            body={
                "account_id": account_id,
                "conversion": conversion,
                "currency": currency,
                "enabled": enabled,
                "event_name": event_name,
                "event_type": event_type,
                "fixed_value_micros": fixed_value_micros,
                "target_id": target_id,
                "value_property": value_property,
                "value_unit": value_unit,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_ad_draft(
        self,
        *,
        brand: str | None = None,
        bidding: dict[str, Any] | None = None,
        call_to_action: str | None = None,
        countries: list[str] | None = None,
        daily_budget_micros: int | None = None,
        descriptions: list[str] | None = None,
        final_url: str | None = None,
        headlines: list[str] | None = None,
        image_url: str | None = None,
        keywords: list[dict[str, Any]] | None = None,
        kind: Literal["ad", "ad_group", "campaign"] | None = None,
        name: str | None = None,
        page_id: str | None = None,
        path1: str | None = None,
        path2: str | None = None,
        primary_text: str | None = None,
        account_id: str | None = None,
        ad_group_id: str | None = None,
        campaign_id: str | None = None,
        reason: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Write a new ad for a person to check.

        Scope: ads.manage. Writes a draft: a new ad in an ad group (ad set
        on Meta), a new ad group with keywords and an ad in a campaign, or
        a new search campaign with its daily budget, bidding, countries and
        an ad group (Google Ads). It is checked against the platform's
        rules (a Google search ad has 3 to 15 headlines of at most 30
        characters and 2 to 4 descriptions of at most 90; a Meta ad has one
        headline, its main text and an image) and waits for a person:
        nothing is made on the platform until approveAdDraft. Writing one
        spends nothing, so an agent writes it under its grant.

        Needs: the ads.manage scope.
        POST /v1/brands/{brand}/ads/drafts
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/ads/drafts",
            path={"brand": brand},
            body={
                "bidding": bidding,
                "call_to_action": call_to_action,
                "countries": countries,
                "daily_budget_micros": daily_budget_micros,
                "descriptions": descriptions,
                "final_url": final_url,
                "headlines": headlines,
                "image_url": image_url,
                "keywords": keywords,
                "kind": kind,
                "name": name,
                "page_id": page_id,
                "path1": path1,
                "path2": path2,
                "primary_text": primary_text,
                "account_id": account_id,
                "ad_group_id": ad_group_id,
                "campaign_id": campaign_id,
                "reason": reason,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_ad_test(
        self,
        *,
        brand: str | None = None,
        campaign_id: str,
        daily_budget_micros: int | None = None,
        kind: Literal["budget", "bidding"],
        name: str | None = None,
        split_percent: int | None = None,
        target_cpa_micros: int | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Start a test inside the ad network.

        Scope: ads.manage, from a person's session (403 for an API token).
        Starts tomorrow on the campaign's own account: a Google Ads custom
        experiment on a search or display campaign whose trial bids to
        target_cpa_micros (kind bidding), or a Meta split test against a
        copy of the campaign with daily_budget_micros (kind budget; the ad
        account must belong to a business). split_percent is the trial's
        share (10 to 90, default 50). It runs long enough for about 30
        conversions in the smaller arm after the trial settles, two to six
        weeks (window_note). 409 `not_active` when the campaign isn't
        running or already has a test; 422 `connector_invalid` when its
        network can't run that kind of test.

        Needs: the ads.manage scope.
        POST /v1/brands/{brand}/ads/tests
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/ads/tests",
            path={"brand": brand},
            body={
                "campaign_id": campaign_id,
                "daily_budget_micros": daily_budget_micros,
                "kind": kind,
                "name": name,
                "split_percent": split_percent,
                "target_cpa_micros": target_cpa_micros,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

