    def create_browser_task(
        self,
        *,
        brand: str | None = None,
        account_id: str | None = None,
        goal: str,
        hosts: list[str] | None = None,
        max_cents: int | None = None,
        max_minutes: int | None = None,
        max_steps: int | None = None,
        operations: list[Literal["read", "act", "sign_in"]] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Queue a browser task.

        Scope: browser.manage. Bounded work a browser worker does on sites
        with no API: the goal, the hosts it may reach (the account's own
        site and the sites it signs in through are added), what it may do
        (`read`; `act` to click, type approved content and submit;
        `sign_in` as `account_id` from the vault), the approved texts it
        may type by name, and ceilings on steps, minutes and AI spend. The
        worker enforces all of it; secrets never reach the model. An
        agent's task is a change like any other: it runs within its
        grants or waits for a person.

        Needs: the browser.manage scope.
        POST /v1/brands/{brand}/browser-tasks
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/browser-tasks",
            path={"brand": brand},
            body={
                "account_id": account_id,
                "goal": goal,
                "hosts": hosts,
                "max_cents": max_cents,
                "max_minutes": max_minutes,
                "max_steps": max_steps,
                "operations": operations,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_bulk_edit(
        self,
        *,
        brand: str | None = None,
        changes: dict[str, Any],
        record_ids: list[str] | None = None,
        saved_query_id: str | None = None,
        smart_list_id: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Run a bulk edit.

        Scope: customers.manage, and only the workspace's owners, signed in, run bulk edits (403 owner_only for
        everyone else, API tokens included; they can preview). Changes the brand's people or companies from a smart
        or static list, a saved query (its record_id or id column, up to 10,000 rows) or ids picked by hand, up to
        50,000 records. The records are fixed now: exactly what the preview counts. It runs in the background: 202
        with the bulk edit, whose status goes queued, running, then done (or failed). Every change is written to each
        record's own history with the bulk edit's id (GET .../records/{record}/history, bulk_edit_id; list moves on
        the timeline), and each changed record is a record.updated or record.archived, as a hand edit is, so rules,
        journeys and webhooks hear of it. It can be undone for 7 days.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/bulk-edits
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/bulk-edits",
            path={"brand": brand},
            body={
                "changes": changes,
                "record_ids": record_ids,
                "saved_query_id": saved_query_id,
                "smart_list_id": smart_list_id,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_connect_request(
        self,
        *,
        ws: str | None = None,
        connector: str,
        expires_in_minutes: int | None = None,
        name: str | None = None,
        reason: str | None = None,
        use_for_verification: bool | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Ask a person to connect a service.

        Scope: integrations.manage. The agent-first way to connect anything:
        returns a one-time link to give the person. They open it, without
        logging in, and paste the key or approve the OAuth sign-in. The
        secret never passes through the agent. Poll
        GET /connect-requests/{id} until status is connected.

        Needs: the integrations.manage scope.
        POST /v1/workspaces/{ws}/connect-requests
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/connect-requests",
            path={"ws": ws},
            body={
                "connector": connector,
                "expires_in_minutes": expires_in_minutes,
                "name": name,
                "reason": reason,
                "use_for_verification": use_for_verification,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

