    def create_query_endpoint(
        self,
        *,
        brand: str | None = None,
        description: str | None = None,
        name: str | None = None,
        params: list[dict[str, Any]] | None = None,
        rate_per_minute: int | None = None,
        row_cap: int | None = None,
        saved_query_id: str | None = None,
        slug: str | None = None,
        status: Literal["active", "disabled"] | None = None,
        version: int | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Publish a query endpoint.

        Scope: customers.manage, and only the workspace's owners and admins, signed in (403 admin_only). Publishes a
        saved query, pinned to a version (default its current one), at slug, for API tokens holding query.endpoints
        and made for this brand. The query reads what the publisher can read now (scopes), whoever calls it.
        Parameters are bound in order as $1, $2, … in the SQL; every $n the SQL uses needs one. 409 when the slug is
        taken.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/query-endpoints
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/query-endpoints",
            path={"brand": brand},
            body={
                "description": description,
                "name": name,
                "params": params,
                "rate_per_minute": rate_per_minute,
                "row_cap": row_cap,
                "saved_query_id": saved_query_id,
                "slug": slug,
                "status": status,
                "version": version,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_record(
        self,
        *,
        brand: str | None = None,
        acquired_via: str | None = None,
        archived: bool | None = None,
        attributes: dict[str, Any] | None = None,
        brand_id: str | None = None,
        identities: list[dict[str, Any]] | None = None,
        name: str | None = None,
        origin: Literal["first_party", "prospect", "crm_sync", "import", "manual"] | None = None,
        source: Literal["manual", "first_party", "crm_sync", "enrichment", "import"] | None = None,
        type: str | None = None,
        version: int | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Add a customer record.

        Scope: customers.manage. Attributes are checked against the type's fields in the catalog; an unknown key is
        refused, so add the field first. Identities say who the record is: email and phone count only when verified
        (default false), and the workspace's own ids, payment customers and domains are trusted as sent. A verified
        identity another record of the same brand already holds is refused with identity_taken; look it up with GET
        .../records/lookup. The record's catalog and its identities are its brand's: the same email in another brand
        is another person there. A person with no name takes first_name and last_name.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/records
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/records",
            path={"brand": brand},
            body={
                "acquired_via": acquired_via,
                "archived": archived,
                "attributes": attributes,
                "brand_id": brand_id,
                "identities": identities,
                "name": name,
                "origin": origin,
                "source": source,
                "type": type,
                "version": version,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

