    def create_social_publication(
        self,
        *,
        brand: str | None = None,
        account_id: str,
        body: str | None = None,
        link_url: str | None = None,
        prompt: str | None = None,
        scheduled_for: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Write a post for the brand's own account.

        Scope: social.manage. A draft of an original post on an X account
        or LinkedIn page or profile from GET .../social/accounts, for a
        person to approve. Write `body` yourself, or leave it out and give
        `prompt`: the workspace's own AI model (the social_posts task)
        drafts it in the background, on its own AI bill, and the post is
        `drafting` until then. `link_url` is tagged with UTM (one campaign
        per account, this post's own utm_content) and goes after the text
        on its own line. The text and link must fit the channel: 280 on X,
        where every link counts as 23, and 3000 on LinkedIn.
        `scheduled_for` posts it at that time once approved; without it,
        it posts as soon as it is approved.

        Needs: the social.manage scope.
        POST /v1/brands/{brand}/social/publications
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/social/publications",
            path={"brand": brand},
            body={
                "account_id": account_id,
                "body": body,
                "link_url": link_url,
                "prompt": prompt,
                "scheduled_for": scheduled_for,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_social_series(
        self,
        *,
        brand: str | None = None,
        account_id: str,
        daily_limit: int | None = None,
        name: str,
        template: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Add a recurring post series.

        Scope: social.manage. A series such as a daily changelog summary on
        the product's own account. It is unapproved until a person
        approves it; then each post handed in for it (POST
        .../series/{id}/posts) goes out with no other approval, up to
        `daily_limit` in any 24 hours. `template` tells the approver what
        it will post: a sample or a description.

        Needs: the social.manage scope.
        POST /v1/brands/{brand}/social/series
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/social/series",
            path={"brand": brand},
            body={"account_id": account_id, "daily_limit": daily_limit, "name": name, "template": template},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_social_watch(
        self,
        *,
        brand: str | None = None,
        auto_draft: bool | None = None,
        brand_id: str | None = None,
        check_every_minutes: int | None = None,
        communities: list[str] | None = None,
        conversion_events: list[str] | None = None,
        daily_limit: int | None = None,
        disclosure: str | None = None,
        exclude_keywords: list[str] | None = None,
        guidance: str | None = None,
        integration_id: str | None = None,
        keywords: list[str] | None = None,
        landing_url: str | None = None,
        name: str | None = None,
        status: Literal["active", "paused"] | None = None,
        channel: Literal["reddit"],
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Watch a channel for posts the brand can help with.

        Scope: social.manage. A watch searches the channel (Reddit: the
        given subreddits, or all of Reddit) every `check_every_minutes` for
        new posts from the last week that contain any keyword and none of
        `exclude_keywords`, with the workspace's own connection. With
        `auto_draft` the workspace's own AI model drafts a reply to up to 5
        new posts a check; nothing is posted until a person approves it.
        Every reply ends with `disclosure`, which says the account belongs
        to the brand ("Disclosure: I work at <brand>." when a brand is set
        and none is given). `landing_url` gets UTM tags per reply, so
        visitors and `conversion_events` come back to the reply that
        brought them. With exactly one connection for the channel, the
        watch uses it.

        Needs: the social.manage scope.
        POST /v1/brands/{brand}/social/watches
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/social/watches",
            path={"brand": brand},
            body={
                "auto_draft": auto_draft,
                "brand_id": brand_id,
                "check_every_minutes": check_every_minutes,
                "communities": communities,
                "conversion_events": conversion_events,
                "daily_limit": daily_limit,
                "disclosure": disclosure,
                "exclude_keywords": exclude_keywords,
                "guidance": guidance,
                "integration_id": integration_id,
                "keywords": keywords,
                "landing_url": landing_url,
                "name": name,
                "status": status,
                "channel": channel,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

