    def create_tracking_campaign(
        self,
        *,
        brand: str | None = None,
        channel: str | None = None,
        landing_url: str | None = None,
        name: str | None = None,
        redirect_links: bool | None = None,
        slug: str | None = None,
        source: str | None = None,
        status: Literal["active", "archived"] | None = None,
        traffic_source: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Create a campaign.

        Scope: analytics.manage. The slug (utm_campaign) comes from the name unless given; the medium comes from the
        channel; the source is cleaned (fb and facebook.com become facebook). Slug, channel and source can't change
        later, because links already shared carry them. Then make links with POST .../links.

        Needs: the analytics.manage scope.
        POST /v1/brands/{brand}/tracking-campaigns
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/tracking-campaigns",
            path={"brand": brand},
            body={
                "channel": channel,
                "landing_url": landing_url,
                "name": name,
                "redirect_links": redirect_links,
                "slug": slug,
                "source": source,
                "status": status,
                "traffic_source": traffic_source,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_tracking_link(
        self,
        id: str,
        *,
        brand: str | None = None,
        redirect: bool | None = None,
        term: str | None = None,
        url: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Make a tagged link.

        Scope: analytics.manage. Tags a page with the campaign's utm_source, utm_medium and utm_campaign, the content and
        term given, and its ofc code. Tags the page already had are replaced; other parameters stay. The same page,
        content and term give back the link already made (200). Links go straight to the page by default: the website
        tracking snippet reads the tags there. With `redirect` (or the campaign's `redirect_links`), the link also gets a
        short redirect link that counts each click first, for places the snippet can't run; asking again for a link
        made without one adds it.

        Needs: the analytics.manage scope.
        POST /v1/brands/{brand}/tracking-campaigns/{id}/links
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/tracking-campaigns/{id}/links",
            path={"id": id, "brand": brand},
            body={"redirect": redirect, "term": term, "url": url},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_traffic_source(
        self,
        *,
        brand: str | None = None,
        click_id: dict[str, Any] | None = None,
        cost: dict[str, Any] | None = None,
        currency: str | None = None,
        name: str | None = None,
        parameters: list[dict[str, Any]] | None = None,
        postback: dict[str, Any] | None = None,
        status: Literal["active", "archived"] | None = None,
        template: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Add a traffic source.

        Scope: analytics.manage. From a `template` (GET .../traffic-source-templates), whose values the other fields
        change, or by hand. A template's postback that needs the brand's own value (REPLACE) is left off unless
        `postback` fills it in: a postback with REPLACE in it can't be saved. Give a tracking campaign the source
        (`traffic_source`), and its redirect clicks keep the source's parameters in their custom fields.

        Needs: the analytics.manage scope.
        POST /v1/brands/{brand}/traffic-sources
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/traffic-sources",
            path={"brand": brand},
            body={
                "click_id": click_id,
                "cost": cost,
                "currency": currency,
                "name": name,
                "parameters": parameters,
                "postback": postback,
                "status": status,
                "template": template,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_transaction(
        self,
        *,
        brand: str | None = None,
        amount_minor: int,
        currency: str,
        description: str | None = None,
        kind: Literal["payment", "refund", "chargeback", "credit"],
        occurred_at: str | None = None,
        product: str | None = None,
        record_id: str | None = None,
        refund_of: str | None = None,
        source_id: str,
        status: Literal["succeeded", "pending", "failed", "reversed"] | None = None,
        user_id: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Record a transaction.

        Scope: customers.manage. A payment, refund, chargeback or credit from your own billing. source_id is your id for it:
        sending the same one again never adds it twice, answers the one saved (200) and updates its status when it changed
        (transaction.updated). The amount is kept in its currency and converted to the brand's at the day's rate
        (brand_amount_minor, null until that rate is known).

        One payment counts once, whichever way it arrives. A succeeded payment or refund with a person (record_id or
        user_id) is also a payment.succeeded or payment.refunded event, which revenue, attribution and the conversions
        sent to ad networks count. When the same payment is already in, from an Order Completed event with the same
        order_id (or, without one, the same person, amount and currency within 15 minutes) or from a billing connector
        with the same source_id, the answer is that transaction (200) and nothing is added or counted again.

        Refunds work the same way. refund_of names the payment by any id it has (see TransactionInput). A refund already
        in from an Order Refunded event with the same refund id (its refund_id, else its messageId), or of the same
        payment and amount within 15 minutes, is that one (200). A refund counts once its payment is known, and lowers
        the conversion sent to ad networks for that payment (Google: a conversion adjustment).

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/transactions
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/transactions",
            path={"brand": brand},
            body={
                "amount_minor": amount_minor,
                "currency": currency,
                "description": description,
                "kind": kind,
                "occurred_at": occurred_at,
                "product": product,
                "record_id": record_id,
                "refund_of": refund_of,
                "source_id": source_id,
                "status": status,
                "user_id": user_id,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_visitor_link(
        self,
        *,
        brand: str | None = None,
        email: str | None = None,
        expires_in_days: int | None = None,
        record_id: str | None = None,
        url: str,
        user_id: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Make a visitor link.

        Scope: customers.manage. A link to your own site for one person, to put in a message you send yourself: your
        product's own email, a text message, a push notification or a QR code. The first browser that opens it joins
        the person, with its visits from before, so a phone or a second computer where they never sign in still
        counts as theirs. The address gets an `ofvisit` token, which the site snippet takes and removes; nothing new
        is needed on the site.

        Name the person with one of `user_id`, `email` or `record_id`, in this brand. `url` must be on one of the
        workspace's brands' domains or a site key's origins. A link names one browser only (the first to open it),
        lasts `expires_in_days` (default 30), and a sign-in on that browser as someone else takes it back, as for a
        forwarded email. Links in email Outflare sends need none of this: their clicks do it already. Recorded as
        `visitor_link.created`.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/visitors/links
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/visitors/links",
            path={"brand": brand},
            body={
                "email": email,
                "expires_in_days": expires_in_days,
                "record_id": record_id,
                "url": url,
                "user_id": user_id,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def create_webhook(
        self,
        *,
        brand: str | None = None,
        categories: list[str] | None = None,
        description: str | None = None,
        enabled: bool | None = None,
        events: list[str] | None = None,
        rule_ids: list[str] | None = None,
        url: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Add a webhook endpoint.

        Scope: webhooks.manage. Outflare POSTs each subscribed event to the URL as JSON, signed the Standard Webhooks
        way (webhook-id, webhook-timestamp and webhook-signature headers), and retries failures with backoff for
        about three and a half hours. The answer includes the signing secret; GET .../secret shows it again.
        The URL must be public https unless the server sets WEBHOOKS_ALLOW_PRIVATE. At most 20 per workspace.

        Needs: the webhooks.manage scope.
        POST /v1/brands/{brand}/webhooks
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/webhooks",
            path={"brand": brand},
            body={
                "categories": categories,
                "description": description,
                "enabled": enabled,
                "events": events,
                "rule_ids": rule_ids,
                "url": url,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def crm_import_preview(
        self,
        id: str,
        *,
        ws: str | None = None,
    ) -> Any:
        """See what an import from another CRM would bring over.

        Scope: integrations.read. Reads the connected CRM (Attio) live: its objects (People, Companies, Deals and custom ones) with their fields, select options and pipeline stages, its lists with their own fields, and how many records, list entries, notes, tasks and members it holds. Each count stops at limit, or when the preview has spent about 15 seconds counting, and says so with capped; filled is how many of the counted records have a value in that field. Changes nothing, in Outflare or in the CRM.

        Needs: the integrations.read scope.
        GET /v1/workspaces/{ws}/integrations/{id}/crm-import-preview
        """
        return self._call(
            "GET",
            "/v1/workspaces/{ws}/integrations/{id}/crm-import-preview",
            path={"id": id, "ws": ws},
        )

    def decide_actions(
        self,
        *,
        ws: str | None = None,
        approve: list[str] | None = None,
        note: str | None = None,
        reject: list[str] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Approve and reject held changes in one go.

        Scope: actions.approve. A batch: approves (and runs) and rejects up to 100 held actions. Each is decided on its own,
        so one that can't be decided doesn't stop the rest; data says what happened to each. An agent never decides its own changes.

        Needs: the actions.approve scope.
        POST /v1/workspaces/{ws}/actions/decide
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/actions/decide",
            path={"ws": ws},
            body={"approve": approve, "note": note, "reject": reject},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

