    def dispute_ai_visibility_claim(
        self,
        *,
        brand: str | None = None,
        key: str,
        kind: Literal["attribute", "objection"] | None = None,
        note: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Say a claim AI answers make about the brand isn't true.

        Scope: seo.manage. Puts the claim on the fixes list (source
        `ai_visibility`, rule `ai_wrong_claim`, on the latest answer that
        made it, with how many answers did in the last 28 days), so someone
        corrects it where the answers read it: the brand's own page on the
        point and the pages the answers cite. Disputing it again reopens a
        done or ignored fix. Audit action `ai_claim.disputed`.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/ai-visibility/claims/dispute
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/ai-visibility/claims/dispute",
            path={"brand": brand},
            body={"key": key, "kind": kind, "note": note},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def download_privacy_export(
        self,
        export: str,
        *,
        brand: str | None = None,
    ) -> Any:
        """Download a privacy export.

        Scope: customers.manage, because the file is someone's personal data in bulk. The export as a gzipped JSON file
        (privacy-export-{id}.json.gz): {"exported_at", "brand": {"id", "name"}, "record": {...}, "tables": {"table":
        [rows]}}, each row with every column but secrets. Each download is recorded in the audit log
        (privacy_export.downloaded). 409 export_not_ready while it is pending or when it failed; 410 export_expired
        once its 7 days are over.

        Needs: the customers.manage scope.
        GET /v1/brands/{brand}/privacy-exports/{export}/download
        """
        return self._call(
            "GET",
            "/v1/brands/{brand}/privacy-exports/{export}/download",
            path={"export": export, "brand": brand},
        )

    def draft_ai_prompts(
        self,
        cohort: str,
        *,
        brand: str | None = None,
        brief: str | None = None,
        count: int | None = None,
        personas: list[str] | None = None,
        topics: list[str] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Draft questions for a cohort.

        Scope: seo.manage. The workspace's own AI (the AI visibility task under Settings, AI model) drafts the questions the brand's buyers ask AI, across every awareness level (problem, solution, competitor, brand) and question type, from the brand's context, the cohort's competitors and the brand's own Search Console queries. They are added with status suggested, source drafted and why; a question taken from a search query carries its monthly demand. Runs skip them until a person keeps them (status active). Answers 202 and drafts in the background.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/ai-cohorts/{cohort}/prompts/draft
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/ai-cohorts/{cohort}/prompts/draft",
            path={"cohort": cohort, "brand": brand},
            body={"brief": brief, "count": count, "personas": personas, "topics": topics},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def draft_review_reply(
        self,
        id: str,
        *,
        brand: str | None = None,
        hint: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Draft an answer to a review.

        Scope: social.manage. Queues a public answer drafted by the
        workspace's own AI model (the review_replies task), on its own AI
        bill, from the review, the reviewer's earlier reviews, the brand's
        context and reply guide, and the brand's past replies. The answer is
        the review with draft.status drafting; it becomes draft (to edit and
        post on the platform yourself), skipped (with the reason, such as a
        review to report instead) or failed. hint asks for another version
        ("shorter"). Drafts are never posted from Outflare. Answers
        connector_needed (409) without an AI model.

        Needs: the social.manage scope.
        POST /v1/brands/{brand}/reviews/{id}/draft
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/reviews/{id}/draft",
            path={"id": id, "brand": brand},
            body={"hint": hint},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def draft_social_publication(
        self,
        id: str,
        *,
        brand: str | None = None,
        prompt: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Have the AI (re)write a draft.

        Scope: social.manage. The workspace's own AI model (the
        social_posts task) writes the draft again in the background, from
        `prompt` (or the one it was given before) and the current text, on
        the workspace's own AI bill. It is `drafting` until then, and a
        draft again after, with status_reason when the AI fell short.

        Needs: the social.manage scope.
        POST /v1/brands/{brand}/social/publications/{id}/draft
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/social/publications/{id}/draft",
            path={"id": id, "brand": brand},
            body={"prompt": prompt},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def draft_social_reply(
        self,
        id: str,
        *,
        brand: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Have the workspace's AI draft a reply.

        Scope: social.manage. Queues a draft by the workspace's own AI model
        (the social_replies task), on its own AI bill. The answer is the
        action, status drafting; it becomes a draft for a person to approve,
        or rejected with the reason when the AI suggests not replying.
        Answers connector_needed without an AI model. A post takes one
        reply at a time.

        Needs: the social.manage scope.
        POST /v1/brands/{brand}/social/items/{id}/draft
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/social/items/{id}/draft",
            path={"id": id, "brand": brand},
            idempotency_key=idempotency_key,
        )

    def draft_story(
        self,
        story: str,
        *,
        brand: str | None = None,
        guidance: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Draft a story's release with AI.

        Scope: seo.manage. Queues the workspace's own AI model to write
        the story's release from its headline, notes, facts and approved
        quotes only (never a draft or withdrawn quote), improving the
        current release when there is one. The draft replaces the
        release, moves the story to `draft` and is checked like any
        release; a person still approves it. Follow `ai_status` on the
        story (drafting, then empty, or failed with `ai_error`). 409 while
        a draft is being written or the story is archived, and
        `connector_needed` without a connected model.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/stories/{story}/draft
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/stories/{story}/draft",
            path={"story": story, "brand": brand},
            body={"guidance": guidance},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

