    def outcomes_report(
        self,
        *,
        ws: str | None = None,
        from_: str | None = None,
        to: str | None = None,
        group_by: Literal["none", "sequence", "brand"] | None = None,
        brand: str | None = None,
        sequence_id: str | None = None,
        mission_id: str | None = None,
        currency: str | None = None,
    ) -> Any:
        """Cost per reply, meeting and deal.

        Scope: outcomes.read. Sends, replies, meetings, deals and spend over a
        period, for the workspace or per sequence or brand, with cost per
        reply, per meeting, per held meeting and per deal. Spend tied to a
        sequence, brand, mailbox or domain is charged to it directly; the
        rest is shared out by each row's share of emails sent. Usage recorded
        only as units (credits) is priced with the workspace's spend rates and
        reported as estimated; usage with no rate is listed under `unpriced`.
        Nothing is converted between currencies. group_by=brand compares
        brands (a row's brand is its sequence's), and brand keeps
        the report to one brand.

        Needs: the outcomes.read scope.
        GET /v1/workspaces/{ws}/outcomes/report
        """
        return self._call(
            "GET",
            "/v1/workspaces/{ws}/outcomes/report",
            path={"ws": ws},
            query={
                "from": from_,
                "to": to,
                "group_by": group_by,
                "brand": brand,
                "sequence_id": sequence_id,
                "mission_id": mission_id,
                "currency": currency,
            },
        )

    def partner_postback(
        self,
        token: str,
        *,
        type: Literal["signup", "lead", "sale", "refund", "custom"] | None = None,
        event_name: str | None = None,
        recurring: str | None = None,
        ref: str | None = None,
        click_id: str | None = None,
        promo_code: str | None = None,
        country: str | None = None,
        customer_id: str | None = None,
        email: str | None = None,
        external_id: str | None = None,
        refund_of: str | None = None,
        amount: str | None = None,
        currency: str | None = None,
    ) -> Any:
        """Report a conversion by URL (incoming postback).

        The program's postback URL, for trackers and backends that can only call a URL. Takes the same fields as
        POST .../partner-conversions from the query string, with the names affiliate networks use as aliases: type
        (or event, goal), ref, click_id (or ref_click, clickid), promo_code (or coupon), customer_id (or user_id),
        email, external_id (or order_id, transaction_id, charge_id, txid), refund_of, amount (in the currency's main
        unit, such as 49.90; or amount_cents), currency, product_id, sub_id, country (or country_code) and occurred_at.

        GET /v1/partner-postbacks/{token}
        """
        return self._call(
            "GET",
            "/v1/partner-postbacks/{token}",
            path={"token": token},
            query={
                "type": type,
                "event_name": event_name,
                "recurring": recurring,
                "ref": ref,
                "click_id": click_id,
                "promo_code": promo_code,
                "country": country,
                "customer_id": customer_id,
                "email": email,
                "external_id": external_id,
                "refund_of": refund_of,
                "amount": amount,
                "currency": currency,
            },
        )

