    def replay_events(
        self,
        *,
        brand: str | None = None,
        batch_id: str | None = None,
        code: str | None = None,
        ids: list[str] | None = None,
        name: str | None = None,
        source: str | None = None,
        status: Literal["rejected", "held"] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Replay rejected or held events.

        Scope: customers.manage. Processes rejected and held events again, after you fixed what they needed (approved
        the name, changed a property's type, freed an identity): either the ones in ids, or every one matching a
        filter (status, code, source, batch_id, name), up to 10,000 a call (more is true when there are others). They
        go back to pending and the job processes them again; each ends with a new status. Accepted, duplicate and
        pending events are left alone and counted in skipped.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/events/replay
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/events/replay",
            path={"brand": brand},
            body={"batch_id": batch_id, "code": code, "ids": ids, "name": name, "source": source, "status": status},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def replay_hook_event(
        self,
        event: str,
        *,
        ws: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Handle a webhook event again.

        Scope: integrations.manage. Queues the event as if it had just arrived, such as after fixing what made it fail.

        Needs: the integrations.manage scope.
        POST /v1/workspaces/{ws}/hook-events/{event}/replay
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/hook-events/{event}/replay",
            path={"event": event, "ws": ws},
            idempotency_key=idempotency_key,
        )

    def reply_support_conversation(
        self,
        id: str,
        *,
        brand: str | None = None,
        assistant_run_id: str | None = None,
        body: str,
        status: Literal["pending", "closed", "open"] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Reply to a customer.

        Scope: inbox.manage. Emails the customer in the same thread: from the support mailbox the conversation came in
        on, or, for one that came by forwarding, through the workspace's email provider from the address the customer
        wrote to (409 `no_email_provider` or `email_domain_not_verified` until that is set up). It is sent in the
        background: the message's `status` goes from sending to sent or failed (with `error`). The address must pass the policy check for mail a person asked for: an unsubscribe from marketing
        doesn't stop it, a bounce or a block does (409 `blocked`). The conversation becomes pending (waiting on the
        customer) unless `status` says otherwise, and the first reply sets `first_reply_at`.

        Needs: the inbox.manage scope.
        POST /v1/brands/{brand}/support/conversations/{id}/replies
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/support/conversations/{id}/replies",
            path={"id": id, "brand": brand},
            body={"assistant_run_id": assistant_run_id, "body": body, "status": status},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def reply_to_inbound_message(
        self,
        id: str,
        *,
        brand: str | None = None,
        body: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Reply from the mailbox the message arrived at, in the same thread.

        Scope: inbox.manage. Goes through the recipient check (a suppressed
        or opted-out address gets 409) and needs the mailbox to be active.
        It is not held to a sequence's sending window or the mailbox's
        pacing, but counts towards its daily limit.

        Needs: the inbox.manage scope.
        POST /v1/brands/{brand}/inbox/{id}/reply
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/inbox/{id}/reply",
            path={"id": id, "brand": brand},
            body={"body": body},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def report(
        self,
        *,
        ws: str | None = None,
        from_: str | None = None,
        to: str | None = None,
        group_by: Literal["day", "week", "sequence", "step", "mailbox", "domain", "brand"] | None = None,
        brand: str | None = None,
        timezone: str | None = None,
        sequence_id: str | None = None,
        mailbox_id: str | None = None,
        domain: str | None = None,
    ) -> Any:
        """Outreach and deliverability report.

        Scope: sequences.read. Sends, leads contacted, new leads and follow-ups,
        failures, policy blocks, bounces, replies (and replied leads), auto-replies,
        opt-outs and unsubscribes, with reply, bounce and opt-out rates. Totals
        for the period, and rows by day, week, sequence, step, mailbox, domain or
        brand. Default period is the last 30 days. A record's brand is its
        sequence's, or its mailbox's when it has no sequence.

        Needs: the sequences.read scope.
        GET /v1/workspaces/{ws}/reports
        """
        return self._call(
            "GET",
            "/v1/workspaces/{ws}/reports",
            path={"ws": ws},
            query={
                "from": from_,
                "to": to,
                "group_by": group_by,
                "brand": brand,
                "timezone": timezone,
                "sequence_id": sequence_id,
                "mailbox_id": mailbox_id,
                "domain": domain,
            },
        )

