    def run_support_assistant(
        self,
        id: str,
        *,
        brand: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Draft a reply with the assistant.

        Scope: inbox.manage. Asks the support assistant now, whatever its setting, about the customer's latest message,
        with the workspace's own AI (409 with the AI's problem, such as `connector_needed`, without one; 409
        `nothing_to_answer` when the customer hasn't written). It answers only from knowledge customers may be told,
        asks one short question back, or hands off: a request for a person and sensitive topics (disputes, legal,
        security, personal data) never reach the AI. A reply must cite what it used, pass the style rules (short, the
        answer first, no filler) and a check that every fact is in what it cites. Nothing is sent: send it with
        `assistant_run_id` on the reply, or discard it.

        Needs: the inbox.manage scope.
        POST /v1/brands/{brand}/support/conversations/{id}/assistant
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/support/conversations/{id}/assistant",
            path={"id": id, "brand": brand},
            idempotency_key=idempotency_key,
        )

    def run_trend(
        self,
        *,
        brand: str | None = None,
        breakdown: str | None = None,
        compare: bool | None = None,
        date_range: dict[str, Any] | None = None,
        display: Literal["line", "bar", "number", "table"] | None = None,
        formula: str | None = None,
        interval: Literal["day", "week", "month"] | None = None,
        series: list[dict[str, Any]],
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Run a trend.

        Scope: analytics.read. One to six series over time from website visits, page views, product events, saved conversions,
        payments and the ad networks' daily numbers (clicks, impressions, spend, conversions), each counted as rows, people,
        a sum or an average, by day, week or month. Optional: a breakdown by a field of each series' rows, a formula between
        series ("A / B" for cost per sign-up), and the period just before (compare). A number tile is a trend read by its totals.
        Runs for at most 30 seconds (query_timeout).

        Needs: the analytics.read scope.
        POST /v1/brands/{brand}/insights/trend
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/insights/trend",
            path={"brand": brand},
            body={
                "breakdown": breakdown,
                "compare": compare,
                "date_range": date_range,
                "display": display,
                "formula": formula,
                "interval": interval,
                "series": series,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

