    def search_workspace(
        self,
        *,
        ws: str | None = None,
        brand: str | None = None,
        q: str,
        kinds: str | None = None,
        limit: int | None = None,
        mode: Literal["words", "meaning"] | None = None,
    ) -> Any:
        """Search records and their history.

        The read scope of each kind searched: record (customers.read: names, attribute text, emails, phones and ids),
        message (emails sent, sequences.read, by subject; and received, inbox.read, by subject and body), meeting and
        deal (outcomes.read) and email (lifecycle email, emails.read, by subject). Every word must match, each as the
        start of a word ("pric" finds pricing), in any language. Results are ranked, records first, with record_id
        and record_name saying whose each one is, and a snippet of the text that matched. A caller kept to some
        brands finds their rows and the shared ones, as on the record timeline.

        GET /v1/workspaces/{ws}/search
        """
        return self._call(
            "GET",
            "/v1/workspaces/{ws}/search",
            path={"ws": ws},
            query={"brand": brand, "q": q, "kinds": kinds, "limit": limit, "mode": mode},
        )

    def send_desktop_report(
        self,
        *,
        accounts: list[dict[str, Any]] | None = None,
        app_version: str | None = None,
        errors: list[dict[str, Any]] | None = None,
        status: Literal["ok", "attention", "broken"] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Report usage from a linked computer.

        With the device token, every `report_every_seconds`. Only numbers: for each AI account signed in on the computer,
        its limit windows (how much is used, when each resets), plan and banked resets; plus the tools it couldn't read,
        by code. An empty report is a heartbeat. Readings go on the account signed in with the same email anywhere in the
        workspace (adding the person to it), else the person's only account for that tool, else a new account owned by
        the person. Sources switched off are left out (`skipped: source_off`).

        POST /v1/desktop/reports
        """
        return self._call(
            "POST",
            "/v1/desktop/reports",
            body={"accounts": accounts, "app_version": app_version, "errors": errors, "status": status},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def send_email(
        self,
        *,
        brand: str | None = None,
        bcc: Any | None = None,
        brand_id: str | None = None,
        cc: Any | None = None,
        data: dict[str, Any] | None = None,
        draft: bool | None = None,
        from_: str | None = None,
        html: str | None = None,
        metadata: dict[str, Any] | None = None,
        provider_id: str | None = None,
        purpose: Literal["transactional", "lifecycle"] | None = None,
        reply_to: Any | None = None,
        send_at: str | None = None,
        subject: str | None = None,
        tags: list[str] | None = None,
        template: str | None = None,
        test: bool | None = None,
        text: str | None = None,
        to: Any,
        topic: str | None = None,
        track: dict[str, Any] | None = None,
        version: int | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Send a transactional or lifecycle email.

        Scope: emails.send. Queues one email through the workspace's email
        provider (`provider_id`, or the default) and answers at once; it
        goes out within seconds on its own queue. Name a `template` (id or
        handle) with `data` for its variables, or send `subject` with
        `html` and/or `text` (which may use variables too). `from` must be
        on a verified sending domain; a template's sender is the default.
        Every recipient is checked against the suppression list when it is
        sent; transactional email still reaches people who unsubscribed
        from marketing, lifecycle email does not, and always carries a
        one-click unsubscribe link. Opens and clicks are tracked only when
        the template or `track` turns them on. The email's `trigger` records
        this call (its request_id is on the Logs page). Send an
        Idempotency-Key so a retry never sends twice. Cold outreach does not
        belong here: use sequences.

        Needs: the emails.send scope.
        POST /v1/brands/{brand}/emails
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/emails",
            path={"brand": brand},
            body={
                "bcc": bcc,
                "brand_id": brand_id,
                "cc": cc,
                "data": data,
                "draft": draft,
                "from": from_,
                "html": html,
                "metadata": metadata,
                "provider_id": provider_id,
                "purpose": purpose,
                "reply_to": reply_to,
                "send_at": send_at,
                "subject": subject,
                "tags": tags,
                "template": template,
                "test": test,
                "text": text,
                "to": to,
                "topic": topic,
                "track": track,
                "version": version,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def send_email_broadcast(
        self,
        id: str,
        *,
        brand: str | None = None,
        send_at: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Send a draft broadcast now or later.

        Scope: emails.send. Checks that the email can go (the template is published, the sender's domain is verified,
        the provider sends lifecycle email), freezes the template's published version and starts, or waits for send_at.
        Each person gets their own email; people who left its topic or all marketing email, opt-in topics they never
        joined, and prospects who never agreed to marketing email are skipped, with why.

        Needs: the emails.send scope.
        POST /v1/brands/{brand}/email-broadcasts/{id}/send
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/email-broadcasts/{id}/send",
            path={"id": id, "brand": brand},
            body={"send_at": send_at},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def send_now(
        self,
        *,
        ws: str | None = None,
        sequence_id: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Send every due step now (test workspaces).

        Sends the next step of every active enrollment at once, without waiting for step delays, the sending
        window or the new-lead cap, so a whole sequence can be tried in a minute. Mailbox daily limits still
        apply. Only in a test workspace; a live one answers 409 `live_workspace`.

        Needs: the sequences.manage scope.
        POST /v1/workspaces/{ws}/test/send-now
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/test/send-now",
            path={"ws": ws},
            body={"sequence_id": sequence_id},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def send_site_consent(
        self,
        *,
        action: Literal["accept_all", "reject_all", "custom", "opt_out", "gpc", "api"],
        analytics: bool | None = None,
        anonymousId: str,
        consent_version: int | None = None,
        gpc: bool | None = None,
        key: str,
        lang: str | None = None,
        marketing: bool | None = None,
        path: str | None = None,
        preferences: bool | None = None,
        region: Literal["eea", "us", "other"] | None = None,
        version: int | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Keep a visitor's consent choice.

        Public: the site key (ofk_) in the body is the authority. What the script sends when a visitor makes or changes
        a choice on the banner, or the site's own code calls outflare.consent. Each category the banner asks about
        becomes a consent (channel web, purpose analytics, marketing or preferences, source consent_banner), and
        marketing also sets Google Consent Mode's ad purposes (channel ads: ad_storage, ad_user_data,
        ad_personalization), which ad send-back reads. Each is kept on the visitor's record when they are known, and
        on their anonymousId until identify joins it to their record. evidence says what they were shown: the banner's
        version and consent version, the region, the action, Global Privacy Control, the language and page. The answer
        sets the of_consent cookie (and of_aid when analytics is allowed) on the site's domain, which browsers keep
        when the request came through the site's own domain. Send the JSON as text/plain to skip the CORS preflight.

        POST /v1/site/consent
        """
        return self._call(
            "POST",
            "/v1/site/consent",
            body={
                "action": action,
                "analytics": analytics,
                "anonymousId": anonymousId,
                "consent_version": consent_version,
                "gpc": gpc,
                "key": key,
                "lang": lang,
                "marketing": marketing,
                "path": path,
                "preferences": preferences,
                "region": region,
                "version": version,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def send_site_cookies(
        self,
        *,
        cookies: list[str] | None = None,
        granted: dict[str, Any] | None = None,
        iframes: list[str] | None = None,
        key: str,
        local: list[str] | None = None,
        path: str | None = None,
        scripts: list[str] | None = None,
        session: list[str] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Report a site's cookies from a browser.

        Public: the site key (ofk_) in the body is the authority. What the website script sends at most once a day per browser:
        the names of the page's cookies and storage keys and the host and first path segment of its scripts and iframes, never
        a value, a query string or who the visitor is. granted is the visitor's choice when the consent banner is on, so what
        was there before they allowed it is flagged. Send the JSON as text/plain to skip the CORS preflight.

        POST /v1/site/cookies
        """
        return self._call(
            "POST",
            "/v1/site/cookies",
            body={
                "cookies": cookies,
                "granted": granted,
                "iframes": iframes,
                "key": key,
                "local": local,
                "path": path,
                "scripts": scripts,
                "session": session,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def send_site_events(
        self,
        *,
        batch: list[dict[str, Any]],
        consent: bool | None = None,
        key: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Send website events.

        Public: the site key (ofk_) in the body is the authority. What the tracking snippet (/site.js) sends: page views
        and track events on a visitor's anonymousId, with context.page, context.campaign (the utm_ tags) and, on page
        views, properties.click_ids, ofc and ref, exactly as the landing page had them. A userId, traits and timestamps
        are ignored: the browser cannot say who someone is. Page addresses keep their query string except the parameters
        the key's excluded_params lists and those always left out (sign-in tokens, passwords, codes, session ids, and any
        value that is an email address); context.page.host is the page's host. The referrer keeps only its origin and
        path. Track names must be plain (Signup Started): dotted names are
        Outflare's own. Your own product links the visitor to a person by sending
        identify with userId and the same anonymousId to POST .../customer-events. Each event joins a visit (a session:
        30 minutes without an event, or a new campaign, starts another), whose id is in context.sessionId; a person's
        first and last touch fields come from their visits. Requests from bots and crawlers are counted, not stored.
        With consent true, the answer sets the visitor's of_aid cookie on the site's domain, which browsers keep when
        events reach Outflare through the site's own domain. Send the JSON as text/plain to skip the CORS preflight.
        At most 20 events per request; 6,000 requests a minute per key, and 250,000 events a day per key, 1,000,000 per
        workspace; an address that keeps sending unknown keys is turned away. A site's own proxy that has the key's proxy
        secret sends it in X-Outflare-Proxy, with the visitor's address in X-Outflare-Client-IP; each visitor's address
        then takes at most 600 requests a minute. A page speed reading is {"type": "vitals", "properties": {"lcp",
        "inp", "cls", "fcp", "ttfb"}, "context": {"page": {"url"}}}, in milliseconds (cls a score): it needs no
        anonymousId, is kept with the page's host and path only, and doesn't count toward the event limits or quota.
        The answer only counts what was taken:
        events are queued and stored a moment later, in the order they arrived, so one the workspace refuses then (an
        unapproved name over its limit) is still counted as accepted.

        POST /v1/site/events
        """
        return self._call(
            "POST",
            "/v1/site/events",
            body={"batch": batch, "consent": consent, "key": key},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def send_site_signup(
        self,
        *,
        anonymousId: str,
        email: str,
        key: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Report a sign-up from the website.

        Public: the site key (ofk_) in the body is the authority. What outflare.signup(email) in the tracking script sends
        when a visitor signs up, for sites whose backend reports nothing to Outflare. It records a signup conversion
        (source browser) for the partner whose link the visitor came from, by the visitor's own visits with a ref, under
        each program's window and credit rule, so the lead shows at once. Anyone can call it with any address, so it pays
        a sign-up reward only when the program sets pay_browser_signups; sales and refunds still come from your server or
        billing. The answer is the same whether or not a partner was credited. Send the JSON as text/plain to skip the
        CORS preflight.

        POST /v1/site/signup
        """
        return self._call(
            "POST",
            "/v1/site/signup",
            body={"anonymousId": anonymousId, "email": email, "key": key},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def send_visitor_people(
        self,
        id: str,
        token: str,
        *,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Receive people from a visitor identification tool.

        Public: the address is the authority, so keep it secret (GET .../visitors/settings gives it, in people_connections).
        Where RB2B, Vector or Warmly send the people they name on your website, from your own account with the tool. One
        person or up to 100 per call, as an object, an array, or under data; field names as the tool sends them (Business
        Email, business_email, workEmail). People with an email address the CRM doesn't have become person records tagged
        with the tool and held for review; people it has are left as they were. Each one is a visitor.person_revealed
        audit event. With reveal_people off, the call is answered with ignored: off and nothing is kept.

        POST /v1/visitor-hooks/{id}/{token}
        """
        return self._call(
            "POST",
            "/v1/visitor-hooks/{id}/{token}",
            path={"id": id, "token": token},
            body={},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def set_ab_test_version(
        self,
        test: str,
        version: str,
        *,
        brand: str | None = None,
        changes: list[dict[str, Any]] | None = None,
        css: str | None = None,
        redirect: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Set a test version's visual changes.

        Scope: analytics.manage. What the visual editor saves, for people and agents: changes replace the version's visual
        changes (FlagChange), and css and redirect, when sent, replace its CSS and the page it sends visitors to ("" removes
        them). The rest of its payload stays. The control is today's page and can't be changed; 409 once the test has ended.
        An agent token can build a draft's versions under its grants, but a change to a version visitors can see (the test
        runs or its flag is on) always waits for a person (202), as do starting and shipping a test. Recorded as
        flag.updated.

        Needs: the analytics.manage scope.
        PUT /v1/brands/{brand}/ab-tests/{test}/versions/{version}
        """
        return self._call(
            "PUT",
            "/v1/brands/{brand}/ab-tests/{test}/versions/{version}",
            path={"test": test, "version": version, "brand": brand},
            body={"changes": changes, "css": css, "redirect": redirect},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def set_account_secret(
        self,
        id: str,
        kind: str,
        *,
        brand: str | None = None,
        value: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Put a secret in the vault.

        Scope: accounts.manage. Sets the account's password, TOTP seed,
        recovery secret or session, sealed with the server's key. It is
        never returned: the account shows only which kinds it holds. An
        agent asking for this always waits for a person, whatever its
        grants: secrets never pass through a model.

        Needs: the accounts.manage scope.
        PUT /v1/brands/{brand}/accounts/{id}/secrets/{kind}
        """
        return self._call(
            "PUT",
            "/v1/brands/{brand}/accounts/{id}/secrets/{kind}",
            path={"id": id, "kind": kind, "brand": brand},
            body={"value": value},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

