    def suggest_ab_tests(
        self,
        *,
        brand: str | None = None,
        brand_id: str | None = None,
        count: int | None = None,
        goal: dict[str, Any] | None = None,
        notes: str | None = None,
        page: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Suggest A/B tests with AI.

        Scope: analytics.manage. The workspace's own AI model proposes tests from the site's busiest pages and the
        goals visitors reach over the last 28 days, the brand's context and the tests already run. Each suggestion
        comes with the engine's own plan for its page and goal (weeks, the lift findable in 8 weeks, a warning).
        Nothing is created: a person makes the flag and the test. 409 connector_needed without an AI model.

        Needs: the analytics.manage scope.
        POST /v1/brands/{brand}/ab-tests/suggestions
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/ab-tests/suggestions",
            path={"brand": brand},
            body={"brand_id": brand_id, "count": count, "goal": goal, "notes": notes, "page": page},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def suggest_stories(
        self,
        *,
        brand: str | None = None,
        brand_id: str,
        brief: str | None = None,
        count: int | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Suggest story ideas with AI.

        Scope: seo.manage. Queues the workspace's own AI model (its PR
        stories task under Settings, AI model) to suggest story ideas
        from the brand, its facts, its experts' topics, its recent
        coverage and the last two weeks of news its topic searches found.
        Each idea is a story with status `idea` and source `ai_ideas`; it
        never states numbers or quotes. Outflare never uses an AI key of
        its own: without a connected model this is 409
        `connector_needed`. The result is the story.ideas_suggested event.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/stories/ideas
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/stories/ideas",
            path={"brand": brand},
            body={"brand_id": brand_id, "brief": brief, "count": count},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

