    def test_webhook(
        self,
        id: str,
        *,
        brand: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Send a test event now.

        Scope: webhooks.manage. Sends a webhook.test event straight away, even to an endpoint that is off, and
        answers with the delivery: status delivered, or failed with the receiver's status code or the error.
        The test is sent once and listed with the endpoint's deliveries with test: true. It never retries. It doesn't
        touch the endpoint's failure streak, last success, error rate or enabled state, so a 410 Gone answer to a
        test doesn't turn the endpoint off.

        Needs: the webhooks.manage scope.
        POST /v1/brands/{brand}/webhooks/{id}/test
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/webhooks/{id}/test",
            path={"id": id, "brand": brand},
            idempotency_key=idempotency_key,
        )

    def track_customer_events(
        self,
        *,
        ws: str | None = None,
        batch: list[dict[str, Any]] | None = None,
        brand_id: str | None = None,
        context: dict[str, Any] | None = None,
        source: str | None = None,
        type: Literal["track", "identify", "page", "screen", "group", "alias"] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Send product events.

        Scope: customers.manage. Sends what people do in your product, in Segment's format: one event, or
        {"batch": [...]} with up to 500 (5 MB). type is track, identify, page, screen, group or alias; camelCase
        (userId, anonymousId, messageId) and snake_case both work, so a product already sending to Segment or
        RudderStack can point here as is. Send it from your servers: the token can change customer records.

        Each event is matched to a person: by userId (a new userId makes a new person, origin first_party), then by a
        verified email in identify's traits (traits.email_verified true), then by anonymousId. When someone proves an
        email that a record without its own user id holds (an import, a CRM sync), that record is merged into them and
        listed in merged; one with another user id is listed as a possible duplicate instead. An anonymous visitor's
        events wait unmatched and join the person when an identify links their anonymousId. Two userIds are never
        merged and an unverified email never matches anyone. identify's traits that match a person field in the
        catalog (firstName is first_name) are written with source first_party; the rest are kept on the event and
        listed in ignored_traits. group makes or finds the company by groupId and adds it to the person's companies.

        A retry with the same messageId is stored once. Each event is accepted, duplicate or rejected on its own, and
        a new track name enters the catalog quarantined until someone approves it.

        Needs: the customers.manage scope.
        POST /v1/workspaces/{ws}/customer-events
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/customer-events",
            path={"ws": ws},
            body={"batch": batch, "brand_id": brand_id, "context": context, "source": source, "type": type},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def track_keywords(
        self,
        site: str,
        *,
        brand: str | None = None,
        country: str | None = None,
        device: Literal["desktop", "mobile"] | None = None,
        frequency: Literal["daily", "weekly"] | None = None,
        from_targets: bool | None = None,
        integration_id: str | None = None,
        keywords: list[str] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Track keywords for a site.

        Scope: seo.manage. Adds up to 100 keywords (and, with `from_targets`, every page's target keyword) for one country and device; keywords already tracked there are skipped. Each is checked weekly by default, or daily, through the workspace's own SERP connection within its monthly budget (about $0.02 a check with DataForSEO, $0.005 with Geonode), and the first check starts now.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/seo-sites/{site}/rankings
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/seo-sites/{site}/rankings",
            path={"site": site, "brand": brand},
            body={
                "country": country,
                "device": device,
                "frequency": frequency,
                "from_targets": from_targets,
                "integration_id": integration_id,
                "keywords": keywords,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def undo_allocation_change(
        self,
        id: str,
        *,
        ws: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Undo a change.

        Scope: sequences.manage. Only the latest change to a mailbox can be
        undone. Undoing an automatic choice also stops the allocator from
        making it again.

        Needs: the sequences.manage scope.
        POST /v1/workspaces/{ws}/allocation/changes/{id}/undo
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/allocation/changes/{id}/undo",
            path={"id": id, "ws": ws},
            idempotency_key=idempotency_key,
        )

    def undo_batch(
        self,
        batch: str,
        *,
        brand: str | None = None,
        mode: Literal["untouched", "everything"],
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Undo a batch.

        Scope: customers.manage. Undoes the batch in the mode you choose: untouched (what nobody changed since) or
        everything (changed records too). Records it created are deleted with their identities, links, events and
        list places; what it added to other records (identities, links, events, list places) is removed; fields it
        set go back to their earlier value while they still hold its value; leads it created go unless a sequence
        used them. It is all one deletion of kind batch in Recently deleted, restorable for 7 days in one step.
        Emails already sent stay, and the timeline marks them as from an undone batch (detail.undone_batch_id).
        Nothing fires for what it removes; batch.undone is recorded (also a webhook event). A large batch (over
        2,000 rows) is undone in the background: 202 with the batch, whose undo.status goes queued, then done or
        failed. 409 batch_already_undone; 409 batch_undo_running.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/batches/{batch}/undo
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/batches/{batch}/undo",
            path={"batch": batch, "brand": brand},
            body={"mode": mode},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def undo_bulk_edit(
        self,
        bulk_edit: str,
        *,
        brand: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Undo a bulk edit.

        Scope: customers.manage, owners only, signed in (403 owner_only). Within 7 days, puts the records back: each
        field it set goes back unless someone changed it since, records it archived are restored, and list moves
        are reversed; what changed since stays and is counted as kept. The undo is a new bulk edit (source undo) that
        writes new history; the bulk edit's own history stays. 202 with the undo. 409 when it was already undone,
        is still running or is itself an undo; 409 undo_expired after 7 days.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/bulk-edits/{bulk_edit}/undo
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/bulk-edits/{bulk_edit}/undo",
            path={"bulk_edit": bulk_edit, "brand": brand},
            idempotency_key=idempotency_key,
        )

    def undo_merge(
        self,
        merge: str,
        *,
        brand: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Undo a merge.

        Scope: customers.manage. Unmerges: the merged record is a record of its own again (no longer merged or
        archived), every row the merge moved goes back to it (identities, links, events, consents, emails, list
        places and the rest), and the kept record's fields the merge filled go back to what they were. What was
        added to the kept record after the merge stays there, and a field changed since the merge keeps its new
        value (listed in not_restored as changed). Nothing fires: no rule, journey or email; record.unmerged is
        recorded (also a webhook event). 409 merge_not_reversible for a merge made before Outflare kept what merges
        move; 409 merge_not_latest while a later merge involves either record (undo the newest first); 409
        merge_already_undone.

        Needs: the customers.manage scope.
        POST /v1/brands/{brand}/merges/{merge}/undo
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/merges/{merge}/undo",
            path={"merge": merge, "brand": brand},
            idempotency_key=idempotency_key,
        )

