    def update_link_building_settings(
        self,
        *,
        brand: str | None = None,
        pitch_cooldown_days: int | None = None,
        recheck_days: int | None = None,
        weekly_budget_percent: int | None = None,
        weekly_reads: bool | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Change link building settings.

        Scope: seo.manage. `pitch_cooldown_days` is how long after a declined
        pitch its website may be pitched again (0 to 365, default 60).
        `weekly_reads` has the weekly SEO snapshot read who links to pages
        that just went from tracked competitors' sitemaps (default on),
        spending at most `weekly_budget_percent` of the connection's monthly
        budget a month on it (1 to 100, default 10). `recheck_days` is how
        often the pages of broken-link prospects nobody has pitched are
        checked again, so links that break later are found
        (`outbound_link.broken`): 0 is never, default 30. A check is free
        apart from the workspace's own AI reading the page. Send only what
        changes.

        Needs: the seo.manage scope.
        PATCH /v1/brands/{brand}/link-building/settings
        """
        return self._call(
            "PATCH",
            "/v1/brands/{brand}/link-building/settings",
            path={"brand": brand},
            body={
                "pitch_cooldown_days": pitch_cooldown_days,
                "recheck_days": recheck_days,
                "weekly_budget_percent": weekly_budget_percent,
                "weekly_reads": weekly_reads,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def update_link_prospect(
        self,
        prospect: str,
        *,
        brand: str | None = None,
        excluded_reason: str | None = None,
        note: str | None = None,
        stage: str | None = None,
        target_url: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Move a link prospect along, or change its page to offer.

        Scope: seo.manage. `stage` moves it: `pitched`, `replied`, `agreed`,
        `live`, `declined`, `removed` (a live link went away), `excluded`
        (with `excluded_reason`), or back to `prospect`. Moving into
        outreach (`pitched`, `replied` or `agreed`) answers 409
        `site_in_outreach` while another prospect on the same website is
        in outreach or was declined in the last 60 days, and 409 `conflict`
        when its domain is on the suppression list or the prospect is
        excluded (move it back to `prospect` first). Each move records
        link_prospect.<stage> (reopened for `prospect`).

        Needs: the seo.manage scope.
        PATCH /v1/brands/{brand}/link-prospects/{prospect}
        """
        return self._call(
            "PATCH",
            "/v1/brands/{brand}/link-prospects/{prospect}",
            path={"prospect": prospect, "brand": brand},
            body={"excluded_reason": excluded_reason, "note": note, "stage": stage, "target_url": target_url},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def update_link_sequence(
        self,
        sequence: str,
        *,
        brand: str | None = None,
        approve_pitches: bool | None = None,
        auto_send_per_day: int | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Turn approval of a sequence's link pitches on or off.

        Scope: sequences.manage. On (the default), each pitch waits for a person to approve it. Off, a pitch is enrolled once its opener is written, at most `auto_send_per_day` a day (10 by default); pitches past that wait (reason `daily_cap`) and go out on a later day. Pitches the AI was unsure about (reason `unsure: ...`) or to a site with a spam score of 30 or more (`spammy_site`) still wait for a person. Send at least one of the two fields.

        Needs: the sequences.manage scope.
        PATCH /v1/brands/{brand}/link-building/sequences/{sequence}
        """
        return self._call(
            "PATCH",
            "/v1/brands/{brand}/link-building/sequences/{sequence}",
            path={"sequence": sequence, "brand": brand},
            body={"approve_pitches": approve_pitches, "auto_send_per_day": auto_send_per_day},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

