        return self._call(
            "PATCH",
            "/v1/workspaces/{ws}/catalog/option-sets/{set}",
            path={"set": set, "ws": ws},
            body={"key": key, "name": name, "options": options},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

