    def update_role(
        self,
        role: str,
        *,
        ws: str | None = None,
        description: str | None = None,
        name: str | None = None,
        scopes: list[str] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Change a role.

        Scope: roles.manage. Changes a role's name, description or scopes; everyone on it gets the change at once, and the API tokens they made lose scopes the role no longer has. Owner can't be changed, and you can't change a role that can do things you can't, or give it a scope you don't hold. A role with workspace-wide permissions can't hold people kept to some brands.

        Needs: the roles.manage scope.
        PATCH /v1/workspaces/{ws}/roles/{role}
        """
        return self._call(
            "PATCH",
            "/v1/workspaces/{ws}/roles/{role}",
            path={"role": role, "ws": ws},
            body={"description": description, "name": name, "scopes": scopes},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def update_rule(
        self,
        id: str,
        *,
        brand: str | None = None,
        brand_id: str | None = None,
        conditions: list[dict[str, Any]] | None = None,
        cooldown_seconds: int | None = None,
        description: str | None = None,
        emit_event: str | None = None,
        fire: Literal["every_time", "once"] | None = None,
        manual_edits: bool | None = None,
        match: Literal["all", "any"] | None = None,
        name: str | None = None,
        record_type: str | None = None,
        trigger: dict[str, Any] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Change a rule.

        Scope: customers.manage. A draft or paused rule changes freely, and a change to what it does raises its version;
        an active one only its name and description, so pause it first.

        Needs: the customers.manage scope.
        PATCH /v1/brands/{brand}/rules/{id}
        """
        return self._call(
            "PATCH",
            "/v1/brands/{brand}/rules/{id}",
            path={"id": id, "brand": brand},
            body={
                "brand_id": brand_id,
                "conditions": conditions,
                "cooldown_seconds": cooldown_seconds,
                "description": description,
                "emit_event": emit_event,
                "fire": fire,
                "manual_edits": manual_edits,
                "match": match,
                "name": name,
                "record_type": record_type,
                "trigger": trigger,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def update_saved_query(
        self,
        saved_query: str,
        *,
        brand: str | None = None,
        chart: Any | None = None,
        description: str | None = None,
        name: str | None = None,
        note: str | None = None,
        sql: str | None = None,
        visibility: Literal["private", "brand"] | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Change a saved query.

        Scope: customers.manage. Send only what changes. A change to sql or chart makes a new version (note says what
        it is), and the old one stays in the history; a new name or description doesn't. visibility shares the query
        with the brand (brand) or makes it yours alone again (private), and only the person who saved it may change
        it. Anyone with customers.manage may change a shared query. An archived query is 409 saved_query_archived.

        Needs: the customers.manage scope.
        PATCH /v1/brands/{brand}/queries/{saved_query}
        """
        return self._call(
            "PATCH",
            "/v1/brands/{brand}/queries/{saved_query}",
            path={"saved_query": saved_query, "brand": brand},
            body={
                "chart": chart,
                "description": description,
                "name": name,
                "note": note,
                "sql": sql,
                "visibility": visibility,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def update_semantic_search(
        self,
        *,
        ws: str | None = None,
        enabled: bool,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Turn meaning-based search on or off.

        Scope: integrations.manage. Off stops the embedding calls and deletes the workspace's vectors; word search carries
        on. On embeds everything again, once a connection that makes embeddings is there.

        Needs: the integrations.manage scope.
        PUT /v1/workspaces/{ws}/semantic-search
        """
        return self._call(
            "PUT",
            "/v1/workspaces/{ws}/semantic-search",
            path={"ws": ws},
            body={"enabled": enabled},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

