    def verify_email(
        self,
        *,
        token: str,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Confirm an email address with its link.

        The link is `<PUBLIC_URL>/verify-email#<token>`, valid 48 hours, sent when an account is made with a password.

        POST /v1/auth/verify-email
        """
        return self._call(
            "POST",
            "/v1/auth/verify-email",
            body={"token": token},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def verify_fix(
        self,
        fix: str,
        *,
        brand: str | None = None,
        note: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Say a fix is out and check it.

        Scope: seo.manage. The callback for whoever made the change, a person or a coding agent: marks the fix done and starts a crawl of its site. A complete crawl that no longer finds the issue confirms it (webhook fix.confirmed); one that still finds it opens it again (fix.reopened). The body is optional. Site audits' and keyword targets' fixes can be checked; the crawl checks the keyword targets too.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/fixes/{fix}/verify
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/fixes/{fix}/verify",
            path={"fix": fix, "brand": brand},
            body={"note": note},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def verify_mailbox(
        self,
        id: str,
        *,
        ws: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Re-check a mailbox's SMTP and IMAP sign-in and its domain's DNS.

        Scope: mailboxes.manage. Runs in the background; poll the mailbox for the result.

        Needs: the mailboxes.manage scope.
        POST /v1/workspaces/{ws}/mailboxes/{id}/verify
        """
        return self._call(
            "POST",
            "/v1/workspaces/{ws}/mailboxes/{id}/verify",
            path={"id": id, "ws": ws},
            idempotency_key=idempotency_key,
        )

    def verify_seo_site(
        self,
        site: str,
        *,
        brand: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Check that you own a site.

        Scope: seo.manage. Looks now for any one of the site's proofs: a
        Google Search Console connection of the workspace that owns a
        property covering the site, the workspace's Outflare tracking tag on
        the start page, or one added from `verification` (a DNS TXT record,
        a meta tag in the start page's head, or a file on the site). Found,
        the site is verified, its limits rise, and a site still on the
        unproved limits moves to the proved defaults. Not found answers 409 `verification_failed`, whose
        message lists the proofs. Outflare checks a verified site again
        every 30 days and lowers its limits if the proof is gone. A test
        workspace's sites pass without a check.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/seo-sites/{site}/verify
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/seo-sites/{site}/verify",
            path={"site": site, "brand": brand},
            idempotency_key=idempotency_key,
        )

    def whoami(
        self,
    ) -> Any:
        """Who the caller is.

        Any session or token. For an API token: its workspace, brand, scopes and expiry, so a client
        holding only a token can find everything else. For a signed-in person: the user (GET /v1/me lists their
        workspaces).

        Needs: any token.
        GET /v1/whoami
        """
        return self._call(
            "GET",
            "/v1/whoami",
        )

    def write_ab_test_learning(
        self,
        test: str,
        *,
        brand: str | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Write a finished A/B test's learning.

        Scope: analytics.manage. The workspace's own AI model writes (or rewrites) what a finished test taught: a
        headline, the learning and a few tags, kept on the test for the library. It is written on its own when a test
        ends, if the workspace has an AI model. Returns a queued AI run (kind learning). 409 unless the test is done;
        409 connector_needed without an AI model.

        Needs: the analytics.manage scope.
        POST /v1/brands/{brand}/ab-tests/{test}/learning
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/ab-tests/{test}/learning",
            path={"test": test, "brand": brand},
            idempotency_key=idempotency_key,
        )

    def write_ab_test_versions(
        self,
        *,
        brand: str | None = None,
        count: int | None = None,
        fields: list[str] | None = None,
        flag: str | None = None,
        outline: list[dict[str, Any]] | None = None,
        prompt: str,
        test: str | None = None,
        version: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Write test versions with AI.

        Scope: analytics.manage. The workspace's own AI model writes new versions of a flag's content from a prompt,
        in the brand's voice, with a key and a one-line rationale each. They are proposals: a person reviews them and
        adds them to the flag (PATCH .../flags/{flag}). 409 connector_needed without an AI model.

        For a no-code test of a page (send test, or a flag such a test runs on), it reads the page instead (as the site
        serves it, or the outline the visual editor sends) and writes each version as changes to the page (output mode
        page), which Outflare turns into checked selectors: text, hide, link, style, a new line or button, or a move.
        With version, it writes more changes for that one version. A person keeps them (PUT .../ab-tests/{test}/versions/{version}).

        Needs: the analytics.manage scope.
        POST /v1/brands/{brand}/ab-tests/versions
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/ab-tests/versions",
            path={"brand": brand},
            body={
                "count": count,
                "fields": fields,
                "flag": flag,
                "outline": outline,
                "prompt": prompt,
                "test": test,
                "version": version,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )

    def write_fix_ticket(
        self,
        ticket: str,
        *,
        brand: str | None = None,
        feedback: str | None = None,
        extra_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> Any:
        """Write a fix ticket's brief with AI.

        Scope: seo.manage. Queues the workspace's own AI model (its Fix tickets task under Settings, AI model) to write the ticket's brief from everything Outflare knows: the brand, the problem and its pages, their search clicks, every other ticket on the subject and what people decided (rejected ones with their reasons), the saved guidelines, and feedback. Send feedback to rewrite it the way you want. Outflare never uses an AI key of its own: without a connected model this is 409 connector_needed. Follow brief_status on the ticket (queued, writing, ready or failed with brief_error); the result is the fix_ticket.written event.

        Needs: the seo.manage scope.
        POST /v1/brands/{brand}/fix-tickets/{ticket}/write
        """
        return self._call(
            "POST",
            "/v1/brands/{brand}/fix-tickets/{ticket}/write",
            path={"ticket": ticket, "brand": brand},
            body={"feedback": feedback},
            extra_body=extra_body,
            idempotency_key=idempotency_key,
        )
